import { useEffect, useState } from "react";
import axios from "axios";

function Dashboard() {
  const [jobs, setJobs] = useState([]);
  const [company, setCompany] = useState("");
  const [role, setRole] = useState("");
  const [status, setStatus] = useState("Applied");
  const [search, setSearch] = useState("");

  // Fetch Jobs
  const fetchJobs = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/jobs");
      setJobs(res.data);
    } catch (error) {
      console.log("Fetch error:", error);
    }
  };

  // Add Job
  const addJob = async () => {
    if (!company.trim() || !role.trim()) {
      alert("Please fill all fields");
      return;
    }

    try {
      const res = await axios.post("http://localhost:5000/api/jobs", {
        company,
        role,
        status,
      });

      setJobs([...jobs, res.data]); // update instantly

      setCompany("");
      setRole("");
      setStatus("Applied");

      alert("Job added successfully!");

    } catch (error) {
      console.log("Add error:", error);
    }
  };

  // Delete Job
  const deleteJob = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/jobs/${id}`);

      setJobs(jobs.filter((job) => job._id !== id && job.id !== id));

    } catch (error) {
      console.log("Delete error:", error);
    }
  };

  // Load Jobs
  useEffect(() => {
    fetchJobs();
  }, []);

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <div className="max-w-5xl mx-auto">

        <h1 className="text-4xl font-bold text-center mb-8">
          Smart Job Tracker 🚀
        </h1>

        {/* Form */}
        <div className="bg-white p-6 rounded-2xl shadow-md">

          <div className="grid md:grid-cols-4 gap-4">

            <input
              type="text"
              placeholder="Company Name"
              value={company}
              onChange={(e) => setCompany(e.target.value)}
              className="border p-3 rounded-lg"
            />

            <input
              type="text"
              placeholder="Role"
              value={role}
              onChange={(e) => setRole(e.target.value)}
              className="border p-3 rounded-lg"
            />

            <select
              value={status}
              onChange={(e) => setStatus(e.target.value)}
              className="border p-3 rounded-lg"
            >
              <option>Applied</option>
              <option>Interview</option>
              <option>Rejected</option>
              <option>Offer</option>
            </select>

            <button
              onClick={addJob}
              className="bg-blue-500 text-white rounded-lg hover:bg-blue-600"
            >
              Add Job
            </button>

          </div>

          {/* Search */}
          <input
            type="text"
            placeholder="Search jobs..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="border p-3 rounded-lg w-full mt-4"
          />
        </div>

        {/* Jobs List */}
        <div className="grid gap-4 mt-8">

          {jobs
            .filter((job) =>
              (job?.company || "")
                .toLowerCase()
                .includes(search.toLowerCase()) ||
              (job?.role || "")
                .toLowerCase()
                .includes(search.toLowerCase())
            )
            .map((job) => (
              <div
                key={job._id || job.id}
                className="bg-white p-5 rounded-2xl shadow-md"
              >
                <h2 className="text-2xl font-semibold">
                  {job.company}
                </h2>

                <p className="text-gray-700 mt-1">
                  {job.role}
                </p>

                <p className="mt-2">
                  Status:
                  <span className="font-bold ml-2">
                    {job.status}
                  </span>
                </p>

                <button
                  onClick={() => deleteJob(job._id || job.id)}
                  className="bg-red-500 text-white px-4 py-2 rounded-lg mt-4 hover:bg-red-600"
                >
                  Delete
                </button>
              </div>
            ))}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
